/**
 * Shared cross-architecture floating-point tolerance for tests that compare
 * a freshly-computed arena/rate-model number against a value derived from
 * the committed golden fixtures (`tests/fixtures/golden/`), which were
 * generated on `linux-arm64` with Node `GOLDEN_GENERATING_NODE` below. See
 * `docs/architecture.md`'s "Determinism scope" for the full explanation of
 * which functions are bit-exact everywhere (`connectome/model.ts`'s
 * `stepModel`/`aggregateOutputs`, which use only `+`/`-`/`*`) versus
 * architecture-sensitive (`arena/sensors.ts`'s `Math.atan2`/`Math.sin`/
 * `Math.cos`/`Math.hypot`, `arena/world.ts`'s `Math.sin`/`Math.cos`/
 * `Math.hypot` in `createWorld`/`stepWorld`, and `connectome/readout.ts`'s
 * `Math.tanh`/`Math.exp`) — this file only restates the numbers the
 * tolerance below is sized from.
 *
 * Measured on GitHub's `ubuntu-latest` (x86_64) runner against the
 * committed arm64 fixtures (`fix/golden-cross-arch` PR diagnostic run,
 * since removed — see that PR's description for the raw report): one
 * `observations` value (out of 4 committed seeds x 60 ticks x 8 channels)
 * differed by ~2.8e-17 absolute / ~3.1e-16 relative — about one float64 ULP
 * — and it did not propagate further in that run: every downstream column
 * (`ratesAfter`, `outputs`, `actions`) round-trips through `Float32Array`
 * (~1.19e-7 relative precision), which absorbed a perturbation that small.
 * Every other committed file regenerated byte-identical on x86_64, and
 * `tests/unit/episode.test.ts`'s golden-vs-fresh score comparison (which
 * runs entirely through `stepWorld`'s float64 world state, not through any
 * `Float32Array`) matched exactly for every committed seed.
 *
 * Important limit of this evidence: it is an *observation* for these four
 * seeds at this graph/config, not a structural guarantee. `world.ts`'s
 * physics integrator stays in float64 throughout and feeds back into the
 * next tick's observation, so a future fixture refresh (a new seed, a new
 * graph, more ticks) could see a divergence that isn't absorbed the way
 * this one was. Two things bound the risk even so: (1) `numbersCloseEnough`
 * below still requires an *exact* match for every integer/discrete field,
 * so a perturbation that crosses a discrete threshold (a food pickup, a
 * hazard contact, a respawn) surfaces as an integer mismatch no tolerance
 * absorbs; (2) `MAX_INEXACT_LEAVES` bounds how many numeric leaves may
 * differ at all, so a *dense* divergence (the signature of a real behavior
 * regression, not sparse cross-arch noise) still fails loudly even where
 * every individual leaf is within tolerance. If either trips after a
 * legitimate fixture refresh, re-measure on the real target runner before
 * assuming it's a behavior regression — see `docs/architecture.md`.
 *
 * This gate is also arch-only, not OS- or Node/V8-version-aware: a
 * darwin-arm64 contributor, or a future Node upgrade on the generating
 * machine, could in principle produce a 1-ULP difference from
 * `GOLDEN_GENERATING_ARCH`'s recorded fixtures and hit the byte-exact path.
 * That would show up as a strict `toBe` failure on a large single-line JSON
 * string; if that ever happens, diff it with `diffCloseEnough` by hand to
 * confirm it is architecture noise (small, sparse) before assuming a
 * regression.
 */

/**
 * Architecture the committed golden fixtures were generated on. An exact
 * (zero-tolerance) comparison is only valid here; everywhere else, use
 * `numbersCloseEnough`/`diffCloseEnough` below.
 */
export const GOLDEN_GENERATING_ARCH = 'arm64';

/**
 * Node version the committed golden fixtures were generated with (matches
 * `.github/workflows/ci.yml`'s pinned `NODE_VERSION` and this repo's dev
 * machine). V8's `Math.*` implementations can change between Node/V8
 * releases, independent of CPU architecture — noted here so a byte-exact
 * failure on `GOLDEN_GENERATING_ARCH` after a Node upgrade is recognized as
 * the same class of issue as a cross-arch difference, not assumed to be a
 * behavior regression.
 */
export const GOLDEN_GENERATING_NODE = 'v22.22.3';

/**
 * Headroom over the measured divergence (this file's doc comment): roughly
 * 9 orders of magnitude over the observed ~2.8e-17 absolute / ~3.1e-16
 * relative difference, and roughly an order of magnitude over the largest
 * plausible single-ULP `Float32Array` rounding-boundary flip (~1.19e-7
 * relative) a double-precision perturbation this small could in principle
 * trigger downstream in an untested seed/tick/channel combination.
 *
 * This tolerance alone is *not* sufficient to rule out a real behavior change:
 * verified empirically (`fix/golden-cross-arch` PR review) that a single
 * float32-ULP change to one graph edge weight, or a `globalGain * (1 +
 * 1e-7)` change, is *individually* within this tolerance on every affected
 * leaf, yet touches 700+ leaves per seed file. `MAX_INEXACT_LEAVES` below
 * is what catches that class of regression; this tolerance alone only
 * protects against per-leaf noise of roughly this magnitude.
 */
export const FLOAT_ABS_TOLERANCE = 1e-6;
export const FLOAT_REL_TOLERANCE = 1e-6;

/**
 * Cross-arch drift is sparse: the measured divergence (this file's doc
 * comment) touched at most one numeric leaf in any single committed file.
 * A real float32-ULP-scale regression is dense — verified empirically
 * (`fix/golden-cross-arch` PR review) that a single float32-ULP change to
 * one graph edge weight, the same change applied to every edge weight, and
 * a `globalGain * (1 + 1e-7)` change each touch 700 to 2,200 numeric leaves
 * per seed file, while passing `FLOAT_ABS_TOLERANCE`/`FLOAT_REL_TOLERANCE`
 * on every individual leaf. Capping the count of not-bit-identical numeric
 * leaves (`diffCloseEnough`'s `inexactLeaves`) — on top of the per-leaf
 * tolerance — is what makes the tolerant comparison path able to catch a
 * dense regression that per-leaf tolerance alone would miss, while still
 * tolerating genuine sparse cross-arch drift with an 8x headroom over the
 * observed maximum of one leaf per file.
 */
export const MAX_INEXACT_LEAVES = 8;

/**
 * `expected`/`actual` are close enough per `FLOAT_ABS_TOLERANCE`/
 * `FLOAT_REL_TOLERANCE` — except when both are integers (`Number.isInteger`),
 * which must match exactly. This is what keeps every discrete/count value
 * (ticks, seed, substeps, respawn counts, food-pickup/hazard-contact
 * counts, graph index/offset arrays, `rngState`, ...) an exact regression
 * gate even off `GOLDEN_GENERATING_ARCH`, with no need to name each field:
 * none of them are ever fractional, and every field that legitimately is
 * fractional (positions, velocities, `distanceTravelled`/`movementScore`,
 * observations, rates, outputs, decoded actions, readout weights/outputs)
 * falls through to the tolerance check instead.
 */
export const numbersCloseEnough = (expected: number, actual: number): boolean => {
  if (Object.is(expected, actual) || expected === actual) return true;
  if (Number.isInteger(expected) && Number.isInteger(actual)) return false;
  const absDiff = Math.abs(expected - actual);
  if (absDiff <= FLOAT_ABS_TOLERANCE) return true;
  const scale = Math.max(Math.abs(expected), Math.abs(actual));
  const relDiff = scale > 0 ? absDiff / scale : absDiff;
  return relDiff <= FLOAT_REL_TOLERANCE;
};

/** Result of `diffCloseEnough`: `mismatches` empty means "matches within tolerance and leaf budget". */
export interface CloseEnoughDiff {
  /** Human-readable mismatch description per divergent leaf/structural difference. */
  mismatches: string[];
  /**
   * Count of numeric leaf pairs that were not bit-identical (`expected !==
   * actual`), whether or not they were within `numbersCloseEnough`'s
   * tolerance. Compare against `MAX_INEXACT_LEAVES` to catch a dense
   * sub-tolerance regression that `mismatches` alone would miss — see this
   * file's doc comment.
   */
  inexactLeaves: number;
}

const walk = (
  expected: unknown,
  actual: unknown,
  path: string,
  mismatches: string[],
  countInexactLeaf: () => void
): void => {
  if (typeof expected === 'number' && typeof actual === 'number') {
    if (expected !== actual) countInexactLeaf();
    if (!numbersCloseEnough(expected, actual)) {
      const absDiff = Math.abs(expected - actual);
      const scale = Math.max(Math.abs(expected), Math.abs(actual));
      const relDiff = scale > 0 ? absDiff / scale : absDiff;
      mismatches.push(
        `${path}: expected ${expected}, got ${actual} (abs diff ${absDiff}, rel diff ${relDiff}, ` +
          `over tolerance abs<=${FLOAT_ABS_TOLERANCE} or rel<=${FLOAT_REL_TOLERANCE}, or an ` +
          'integer field requiring an exact match)'
      );
    }
    return;
  }

  if (Array.isArray(expected) || Array.isArray(actual)) {
    if (!Array.isArray(expected) || !Array.isArray(actual)) {
      mismatches.push(`${path}: expected array=${Array.isArray(expected)}, got array=${Array.isArray(actual)}`);
      return;
    }
    if (expected.length !== actual.length) {
      mismatches.push(`${path}: expected length ${expected.length}, got ${actual.length}`);
      return;
    }
    for (let index = 0; index < expected.length; index += 1) {
      walk(expected[index], actual[index], `${path}[${index}]`, mismatches, countInexactLeaf);
    }
    return;
  }

  if (
    expected !== null &&
    actual !== null &&
    typeof expected === 'object' &&
    typeof actual === 'object'
  ) {
    const expectedKeys = new Set(Object.keys(expected as object));
    const actualKeys = new Set(Object.keys(actual as object));
    for (const key of expectedKeys) {
      if (!actualKeys.has(key)) mismatches.push(`${path}.${key}: missing from actual (present in committed fixture)`);
    }
    for (const key of actualKeys) {
      if (!expectedKeys.has(key)) mismatches.push(`${path}.${key}: unexpected in actual (not in committed fixture)`);
    }
    for (const key of expectedKeys) {
      if (actualKeys.has(key)) {
        walk(
          (expected as Record<string, unknown>)[key],
          (actual as Record<string, unknown>)[key],
          `${path}.${key}`,
          mismatches,
          countInexactLeaf
        );
      }
    }
    return;
  }

  if (!Object.is(expected, actual)) {
    mismatches.push(`${path}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
};

/**
 * Recursive structural comparison built on `numbersCloseEnough`: numbers
 * use the tolerance rule above (and are counted in `inexactLeaves` when not
 * bit-identical, regardless of tolerance), strings/booleans/array
 * lengths/object key sets must always match exactly. `path` seeds the
 * mismatch labels (typically a filename or a short root label).
 */
export const diffCloseEnough = (expected: unknown, actual: unknown, path: string): CloseEnoughDiff => {
  const mismatches: string[] = [];
  let inexactLeaves = 0;
  walk(expected, actual, path, mismatches, () => {
    inexactLeaves += 1;
  });
  return { mismatches, inexactLeaves };
};
